// 공통 준비: ctx=data.context(+8), setting=ctx.setting(+8), tps=setting.tick_per_second(0x12f8), game=data.cache.game(vtable 0x28=tick), tutorial=ctx.tutorial(+0x38), team=player.info.team(0x930), enemy=1-team.
